'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/card/md-gb-card.js';
import {CardElement} from '@material/web/labs/gb/components/card/card-element.js';

/**
 * A Material Design component. Wraps <md-gb-card>.
 * Docs: https://material-web.dev/3.0/components/card/
 */
export const MdCard = createComponent({
  react: React,
  tagName: 'md-gb-card',
  elementClass: CardElement,
});

export type MdCardProps = React.ComponentProps<typeof MdCard>;
